const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Seoul',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(now);

const year = Number(parts.find((p) => p.type === 'year')?.value);
const month = Number(parts.find((p) => p.type === 'month')?.value);
const day = Number(parts.find((p) => p.type === 'day')?.value);

if (!year || !month || !day) {
  throw new Error('Failed to resolve current date in Asia/Seoul.');
}

const syncYears = month >= 7 ? [year, year + 1] : [year];
const requestedAt = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Seoul',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
}).format(now).replace(' ', 'T');

return syncYears.map((syncYear) => ({
  json: {
    syncYear,
    requestedAtKst: requestedAt,
    triggerMonth: month
  }
}));

const responses = $input.all();
const rowsByDate = new Map();
const yearsWithApiData = new Set();
const customRecurringHolidays = [
  { mmdd: '0501', name: '\uadfc\ub85c\uc790\uc758 \ub0a0' },
  { mmdd: '1231', name: '\ucc3d\ub9bd\uae30\ub150\uc77c\ub300\ud734' }
];

function normalizeItems(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  return [raw];
}

for (const item of responses) {
  const apiItems = normalizeItems(item.json?.response?.body?.items?.item);
  for (const holiday of apiItems) {
    const locdate = String(holiday?.locdate ?? '').trim();
    if (!/^\d{8}$/.test(locdate)) continue;

    const sourceYear = Number(locdate.slice(0, 4));
    const holidayDate = `${locdate.slice(0, 4)}-${locdate.slice(4, 6)}-${locdate.slice(6, 8)}`;
    const holidayName = String(holiday?.dateName ?? '').trim() || '\uc774\ub984\uc5c6\uc74c';

    rowsByDate.set(holidayDate, {
      holidayDate,
      holidayName,
      isHoliday: 1,
      sourceType: 'api',
      sourceYear
    });
    yearsWithApiData.add(sourceYear);
  }
}

const syncedYears = [...yearsWithApiData].sort((a, b) => a - b);
if (syncedYears.length === 0) {
  throw new Error('No holiday data was returned from the public holiday API.');
}

for (const year of syncedYears) {
  for (const customHoliday of customRecurringHolidays) {
    const holidayDate = `${year}-${customHoliday.mmdd.slice(0, 2)}-${customHoliday.mmdd.slice(2, 4)}`;
    if (rowsByDate.has(holidayDate)) continue;

    rowsByDate.set(holidayDate, {
      holidayDate,
      holidayName: customHoliday.name,
      isHoliday: 1,
      sourceType: 'custom',
      sourceYear: year
    });
  }
}

const rows = [...rowsByDate.values()].sort((a, b) => a.holidayDate.localeCompare(b.holidayDate));
const payloadJson = JSON.stringify(rows).replace(/'/g, "''");
const replaceYears = syncedYears.join(', ');
const mergeQuery = `DECLARE @payload NVARCHAR(MAX) = N'${payloadJson}';
DECLARE @mergeResults TABLE (ActionName NVARCHAR(10));
DECLARE @sourceRows TABLE (
    HolidayDate DATE NOT NULL,
    HolidayName NVARCHAR(100) NOT NULL,
    IsHoliday BIT NOT NULL,
    SourceType NVARCHAR(20) NOT NULL,
    SourceYear INT NOT NULL
);

INSERT INTO @sourceRows (
    HolidayDate,
    HolidayName,
    IsHoliday,
    SourceType,
    SourceYear
)
SELECT
    CAST(JSON_VALUE([value], '$.holidayDate') AS date) AS HolidayDate,
    CAST(JSON_VALUE([value], '$.holidayName') AS nvarchar(100)) AS HolidayName,
    CAST(JSON_VALUE([value], '$.isHoliday') AS bit) AS IsHoliday,
    CAST(JSON_VALUE([value], '$.sourceType') AS nvarchar(20)) AS SourceType,
    CAST(JSON_VALUE([value], '$.sourceYear') AS int) AS SourceYear
FROM OPENJSON(@payload);

MERGE TsMgmt.dbo.HolidayCalendarKR AS target
USING @sourceRows AS source
    ON target.HolidayDate = source.HolidayDate
WHEN MATCHED THEN
    UPDATE SET
        HolidayName = source.HolidayName,
        IsHoliday = source.IsHoliday,
        SourceType = source.SourceType,
        SourceYear = source.SourceYear,
        UpdatedAt = SYSDATETIME()
WHEN NOT MATCHED BY TARGET THEN
    INSERT (
        HolidayDate,
        HolidayName,
        IsHoliday,
        SourceType,
        SourceYear,
        CreatedAt,
        UpdatedAt
    )
    VALUES (
        source.HolidayDate,
        source.HolidayName,
        source.IsHoliday,
        source.SourceType,
        source.SourceYear,
        SYSDATETIME(),
        SYSDATETIME()
    )
WHEN NOT MATCHED BY SOURCE AND target.SourceYear IN (${replaceYears}) THEN
    DELETE
OUTPUT $action INTO @mergeResults (ActionName);

SELECT
    '${syncedYears.join(',')}' AS SyncedYears,
    COUNT(1) AS PayloadCount,
    SUM(CASE WHEN SourceType = 'api' THEN 1 ELSE 0 END) AS ApiHolidayCount,
    SUM(CASE WHEN SourceType = 'custom' THEN 1 ELSE 0 END) AS CustomHolidayCount,
    (SELECT COUNT(1) FROM @mergeResults WHERE ActionName = 'INSERT') AS InsertedCount,
    (SELECT COUNT(1) FROM @mergeResults WHERE ActionName = 'UPDATE') AS UpdatedCount,
    (SELECT COUNT(1) FROM @mergeResults WHERE ActionName = 'DELETE') AS DeletedCount,
    CONVERT(VARCHAR(19), SYSDATETIME(), 120) AS SyncedAt
FROM @sourceRows;`;

return [{
  json: {
    syncedYears,
    payloadCount: rows.length,
    apiHolidayCount: rows.filter((row) => row.sourceType === 'api').length,
    customHolidayCount: rows.filter((row) => row.sourceType === 'custom').length,
    mergeQuery
  }
}];
